def is_strictly_increasing(sequence):
    """
    Check if the given sequence is strictly increasing.

    :param sequence: List of integers
    :return: Boolean value indicating if the sequence is strictly increasing
    """
    return all((sequence[i] < sequence[i + 1] for i in range(len(sequence) - 1)))

def can_be_made_increasing_by_erasing_one(sequence):

    def is_strictly_increasing(subsequence):
        return all((subsequence[i] < subsequence[i + 1] for i in range(len(subsequence) - 1)))
    n = len(sequence)
    for i in range(n):
        subsequence = sequence[:i] + sequence[i + 1:]
        if is_strictly_increasing(subsequence):
            return True
    return False

def almost_increasing_sequence(sequence):
    return can_be_made_increasing_by_erasing_one(sequence)

